ces": ["Laser Cutting", "Bending", "Hardware Insertion", "Plating", "Powder Coating", "Tapping", "Tumbling"], "laserCuttingSpecs": [{"mm": "Fiber laser", "inch": "Fiber laser", "label": "Cutting process"}, {"mm": "0.127 mm", "inch": "0.005\\"", "label": "Cut tolerance +/-"}, {"mm": "0.762 mm per 304.8 mm", "inch": "+/-0.030 per foot", "label": "Flatness tolerance before cutting"}, {"mm": "12.7 mm x 19.05 mm", "inch": ".500\\" x .750\\"", "label": "Min part size"}, {"mm": "1117.6 mm x 762 mm", "inch": "44\\" x 30\\"", "label": "Max part size"}, {"mm": "2.413 mm", "inch": ".095\\"", "label": "Recommended Min hole size"}, {"mm": "1.448 mm", "inch": ".057\\"", "label": "Min hole size"}, {"mm": "3.175 mm", "inch": ".125\\"", "label": "Min bridge size"}, {"mm": "1.905 mm", "inch": ".075\\"", "label": "Min hole to edge distance"}, {"mm": "0.381 mm", "inch": ".015\\"", "label": "Tab and slot tolerance"}], "available_services": [1, 3, 6, 10, 11, 7, 12], "powderCoatingSpecs": [{"mm": "25.4 mm x 76.2 mm", "inch": "1\\" x 3\\"", "label": "Min powder coating part size"}, {"mm": "762 mm x 914.4 mm", "inch": "30\\" x 36\\"", "label": "Max powder coating part size"}]}}	{"text": "HRP&O steel is much smoother and easier to finish than the cheaper \\"mill finished hot-roll\\" that most steel centers sell. HRP&O is just hot-rolled steel that is subjected to an acid bath to remove scale mill. Then it has some dry oil applied to prevent rusting. Overall, it has a nicer finish.", "image": "/uploads/metals/hrpo-about.png", "title": "What is HRP&O Carbon Steel?", "capabilities": {"text": "With A36/A1018 HRP&O sheet metal, you can fabricate a wide array of products including structural beams, automotive components, machinery parts, and industrial equipment. Its superior formability and weldability make it ideal for creating frames, brackets, supports, and enclosures. Additionally, its robustness and durability allow for the manufacturing of load-bearing structures and components that require high strength and resilience, ensuring reliability and longevity in demanding applications.", "items": ["Structural beams and supports", "Automotive frames and components", "Machinery and equipment parts", "Construction and building materials", "Industrial enclosures and cabinets", "Agricultural equipment", "Heavy-duty brackets and braces", "Metal fabrication projects", "And so much more!"], "title": "What can you make with HRP&O Carbon Steel parts"}, "featureChart": [{"label": "Strength", "rating": 3}, {"label": "Weldability", "rating": 4}, {"label": "Formability", "rating": 5}, {"label": "Heat Treating", "rating": 3}, {"label": "Corrosion Resistance", "rating": 3}, {"label": "Toughness", "rating": 3}, {"label": "Machinability", "rating": 4}, {"label": "Strength-to-Weight Ratio", "rating": 3}]}	[{"answer": "Thicknesses offered include two variations including .187\\"(4.75mm) and .250\\"(6.35mm).", "question": "What thicknesses does DMS Engineering offer HRP&O Carbon Steel in?"}, {"answer": "At DMS Engineering, HRP&O Carbon Steel is supported with both instant and custom quoting depending on part size. The smallest part allowed is .25\\" x .375\\", while instant quotes go up to 30\\" x 44\\". For dimensions up to 30\\" x 56\\", a custom quote is needed.", "question": "What are the minimum and maximum sizes for cutting HRP&O Carbon Steel?"}, {"answer": "You can add the following services to your HRP&O Carbon Steel parts: Bending, Dimple Forming, Hardware Insertion, Plating, Powder Coating, Tapping, and Tumbling", "question": "What additional services are available for HRP&O Carbon Steel?"}]	{}	22	2026-03-25 18:39:45.535559	2026-04-12 12:46:10.272606	{}
